_satellite.__registerScript('https://assets.adobedtm.com/28fd456592e1/474b779db7d1/849904c4cc1d/RCdc36ca512a7f47f2afadf40f5693a465-source.min.js', "\n\n<!-- Floodlight via gtag (safe: keeps dataLayer as Array, creates gtag stub, prevents duplicates, falls back if environment is broken) -->\n<script>\n  (function () {\n    // 1) Ensure dataLayer is an Array (gtag requires this)\n    window.dataLayer = window.dataLayer || [];\n\n    // If some rule/extension overwrote dataLayer as an object, do NOT try to use gtag — fire fallback pixel.\n    if (!Array.isArray(window.dataLayer)) {\n      console.warn(\"dataLayer is not an Array; firing fallback pixel.\");\n\n      var ord0 = Date.now();\n      var img0 = new Image(1, 1);\n      img0.src =\n        \"https://ad.doubleclick.net/ddm/activity/\" +\n        \"src=8835225;type=df;cat=itc-d0;ord=\" + ord0 + \"?\";\n\n      return;\n    }\n\n    // 2) Ensure gtag exists as a stub (queues calls into dataLayer until gtag.js is ready)\n    window.gtag = window.gtag || function () { window.dataLayer.push(arguments); };\n\n    // 3) Prevent duplicate firing\n    if (window.__floodlightFired) return;\n    window.__floodlightFired = true;\n\n    // 4) Fire (will queue if gtag.js hasn’t finished loading yet)\n    try {\n      window.gtag(\"event\", \"conversion\", {\n        allow_custom_scripts: true,\n        send_to: \"DC-8835225/df/itc-d0+standard\"\n      });\n\n      console.log(\"Floodlight queued/fired via gtag\");\n    } catch (e) {\n      console.warn(\"gtag call failed; firing fallback pixel.\", e);\n\n      var ord1 = Date.now();\n      var img1 = new Image(1, 1);\n      img1.src =\n        \"https://ad.doubleclick.net/ddm/activity/\" +\n        \"src=8835225;type=df;cat=itc-d0;ord=\" + ord1 + \"?\";\n\n      console.log(\"Fallback pixel fired from dc pixel gtagid rule\");\n    }\n  })();\n</script>\n");